@if($canManage)<x-form-sheet id="site-create-sheet" title="Ajouter un site" description="Créez un site de stockage ou de dispensation et rattachez-le à une formation sanitaire."><form method="post" action="{{ route('organizations.dispensing-sites.store',$organization) }}">@csrf<div class="form-grid"><label class="field">Formation sanitaire *<select id="site-create-facility" name="health_facility_id" required><option value="">Sélectionner</option>@foreach($facilities as $item)<option value="{{ $item->id }}">{{ $item->name }}</option>@endforeach</select></label><label class="field">Type *<select name="site_type" required>@foreach($types as $value=>$label)<option value="{{ $value }}">{{ $label }}</option>@endforeach</select></label><label class="field">Nom *<input name="name" required></label><label class="field">Code *<input name="code" required></label><label class="field">Emplacement<input name="location"></label><label class="field">Département<select id="site-create-department" name="department_id"><option value="">Sans département</option>@foreach($facilities as $facility)@foreach($facility->departments as $item)<option value="{{ $item->id }}" data-facility="{{ $facility->id }}">{{ $item->name }}</option>@endforeach @endforeach</select></label><label class="field">Pharmacie<select id="site-create-pharmacy" name="pharmacy_id"><option value="">Sans pharmacie</option>@foreach($facilities as $facility)@foreach($facility->pharmacies as $item)<option value="{{ $item->id }}" data-facility="{{ $facility->id }}">{{ $item->name }}</option>@endforeach @endforeach</select></label><label class="field check"><input type="checkbox" name="is_active" value="1" checked> Site actif</label></div><div class="sheet-actions"><button class="btn outline" type="button" data-sheet-close="site-create-sheet">Annuler</button><button class="btn primary">Ajouter le site</button></div></form></x-form-sheet>@endif
