@if($canManage)<script>const facility=document.getElementById('site-create-facility'),department=document.getElementById('site-create-department'),pharmacy=document.getElementById('site-create-pharmacy');const filter=(select,id)=>[...select.options].forEach((option,index)=>{if(index===0)return;option.hidden=option.dataset.facility!==id;option.disabled=option.hidden;if(option.hidden&&option.selected)select.value='' });const refresh=()=>{filter(department,facility.value);filter(pharmacy,facility.value)};facility?.addEventListener('change',refresh);refresh();@if($errors->any())document.addEventListener('DOMContentLoaded',()=>document.getElementById('site-create-sheet')?.showModal());@endif</script>@endif
